    // Added after the frozen Windows Build. Editor-only verification; no Runtime changes.
    [InitializeOnLoad]public static class ToyTrainFocusedTests
    {
        static ToyTrainFocusedTests(){EditorApplication.update+=Poll;}
        public static void Run(){SessionState.SetBool("TrainFocused",true);ToyTrainEditor.Play();}
        static void Poll(){if(EditorApplication.isPlaying&&SessionState.GetBool("TrainFocused",false)&&ToyTrainFixture.Instance&&ToyTrainFixture.Instance.Ready){SessionState.EraseBool("TrainFocused");new GameObject("EXPLICIT EDITOR FOCUSED QA").AddComponent<FocusedTrainProbe>();}}
    }
    public sealed class FocusedTrainProbe:MonoBehaviour
    {
        [System.Serializable]public class Result{public string method="Editor-only automatic existing input-field/API. Not OS R. Same frozen Runtime source as Windows.";public bool attachedBeforeR,passed;public ToyTrainFixture.State before,immediate,settled;}
        IEnumerator Start()
        {
            Time.captureFramerate=50;var f=ToyTrainFixture.Instance;var input=f.gameObject.AddComponent<TrainInputDriver>();f.Retry();yield return new WaitForSeconds(.6f);
            input.Move=1;float end=Time.time+2;
            while(Time.time<end){if(f.Mover.SupportedTrain&&f.Body.position.x-f.Train.Position.x>-.15f)break;yield return new WaitForFixedUpdate();}
            input.Move=0;yield return new WaitForSeconds(.3f);end=Time.time+13;
            while(Time.time<end&&f.Train.Position.x-ToyTrainFixture.Offset<5.05f)yield return new WaitForFixedUpdate();
            var result=new Result();result.attachedBeforeR=f.Rope.TryAttach(f.Hook.transform.position)&&f.Mover.IsGrounded&&f.Mover.SupportedTrain;
            result.before=new ToyTrainFixture.State(f);f.Retry();result.immediate=new ToyTrainFixture.State(f);yield return new WaitForSeconds(.6f);result.settled=new ToyTrainFixture.State(f);
            result.passed=result.attachedBeforeR&&!f.Rope.IsAttached&&f.Rope.ActiveHookPoint==null&&!f.Mover.SupportedTrain&&f.Mover.IsGrounded&&Vector2.Distance(f.Body.position,f.Spawn)<.18f&&Vector2.Distance(f.Train.Position,ToyTrainFixture.G(0,-.3f))<.01f&&f.Train.Velocity==Vector2.zero&&f.Resource.CurrentLength==24&&f.Rope.SelectedRopeLength==7&&f.Builder.GeneratedPlatformCount==0;
            f.Write("FocusedAttachedR.json",result);Debug.Log("TRAIN_FOCUSED_ATTACHED_R "+result.passed);EditorApplication.Exit(result.passed?0:2);
        }
    }
}
