        }
        BoxCollider2D Floor(string n,float x,float y,float w,float h,Color c)
        {var o=new GameObject(n);o.transform.position=G(x,y);o.transform.localScale=new Vector3(w,h,1);o.AddComponent<SpriteRenderer>();o.AddComponent<SolidSprite>().Color=c;var b=o.AddComponent<BoxCollider2D>();o.AddComponent<SolidSwingSurface>();Block(o.transform,"True walking rim",new Vector2(0,.495f),new Vector2(1,.01f),new Color(.83f,.72f,.52f),4);return b;}
