        {var g=new GameObject(name);g.transform.SetParent(parent,false);g.transform.localPosition=new Vector3(pos.x,pos.y,-.03f*order);g.transform.localScale=new Vector3(scale.x,scale.y,1);g.AddComponent<SpriteRenderer>().sortingOrder=order;g.AddComponent<SolidSprite>().Color=c;}
        static void Disc(Transform p,string n,Vector2 pos,float radius,Color color,int order)
        {var g=new GameObject(n);g.transform.SetParent(p,false);g.transform.localPosition=new Vector3(pos.x,pos.y,-.03f*order);var mesh=new Mesh();var v=new Vector3[33];var tris=new int[32*3];for(int i=0;i<32;i++){float a=i*Mathf.PI*2/32;v[i+1]=new Vector3(Mathf.Cos(a)*radius,Mathf.Sin(a)*radius,0);tris[i*3]=0;tris[i*3+1]=i+1;tris[i*3+2]=(i+1)%32+1;}mesh.vertices=v;mesh.triangles=tris;mesh.RecalculateBounds();g.AddComponent<MeshFilter>().sharedMesh=mesh;var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=new Material(Shader.Find("Sprites/Default")){color=color};r.sortingOrder=order;}
        void TrainArt(Transform t)
        {
            Block(t,"Wood body",new Vector2(0,-.05f),new Vector2(4.8f,1.2f),new Color(.55f,.32f,.14f),5);
