        [Serializable]public class State
        {public Vector2 player,velocity,train,trainVelocity;public bool grounded,onTrain,attached,failure;public float input,remaining,selected,wait;public int bridges,turns;public State(ToyTrainFixture f){player=f.Body.position;velocity=f.Body.linearVelocity;train=f.Train.Position;trainVelocity=f.Train.Velocity;grounded=f.Mover.IsGrounded;onTrain=f.Mover.SupportedTrain;attached=f.Rope.IsAttached;failure=f.Respawn.IsFailureVisible;input=f.Mover.MovementInput;remaining=f.Resource.CurrentLength;selected=f.Rope.SelectedRopeLength;wait=f.Train.WaitRemaining;bridges=f.Builder.GeneratedPlatformCount;turns=f.Train.Turns;}}
