using UnityEngine;
namespace HimoHito
{
    [DefaultExecutionOrder(-300)]
    [RequireComponent(typeof(Rigidbody2D),typeof(BoxCollider2D))]
    public sealed class ToyTrainPlatform:MonoBehaviour
    {
        public const float Travel=5.5f,Speed=1.8f,Acceleration=1.2f,InitialWait=4f,TurnWait=2f;
        Rigidbody2D body;BoxCollider2D deck;Vector2 start;float wait;int direction=1;
        public int Turns{get;private set;}public int Resets{get;private set;}
        public Vector2 Velocity=>body.linearVelocity;
        public RigidbodyType2D BodyType=>body.bodyType;
        public Vector2 Position=>body.position;
        public float WaitRemaining=>wait;
        public void Initialize(){body=GetComponent<Rigidbody2D>();deck=GetComponent<BoxCollider2D>();start=body.position;ResetForRetry();}
        public void ResetForRetry(){if(!body)return;body.position=start;transform.position=start;body.linearVelocity=Vector2.zero;body.angularVelocity=0;direction=1;wait=InitialWait;Turns=0;Resets++;}
        public bool CanSupport(Collider2D player)=>player.bounds.center.y>deck.bounds.max.y&&player.bounds.min.y>=deck.bounds.max.y-.16f;
        void FixedUpdate()
        {
            if(!body)return;
            if(body.bodyType!=RigidbodyType2D.Kinematic){enabled=false;Debug.LogError("Toy train unexpectedly lost its Kinematic body type");return;}
            if(wait>0){wait=Mathf.Max(0,wait-Time.fixedDeltaTime);body.linearVelocity=Vector2.zero;return;}
            float target=start.x+(direction>0?Travel:0);float remaining=(target-body.position.x)*direction;
            float desired=direction*Mathf.Min(Speed,Mathf.Sqrt(Mathf.Max(0,2*Acceleration*remaining)));
            float v=Mathf.MoveTowards(body.linearVelocity.x,desired,Acceleration*Time.fixedDeltaTime);
            if(remaining<.016f&&Mathf.Abs(v)<.24f){body.position=new Vector2(target,start.y);v=0;direction=-direction;wait=TurnWait;Turns++;}
            body.linearVelocity=new Vector2(v,0);
        }
    }
}

