namespace HimoHitoToyTrain
{
    [DefaultExecutionOrder(-10000)]public sealed class TrainInputDriver:MonoBehaviour
    {public float Move;public bool Jump;static FieldInfo M=typeof(PlayerMover).GetField("moveInput",ToyTrainFixture.Private),J=typeof(PlayerMover).GetField("jumpBufferTimer",ToyTrainFixture.Private);void FixedUpdate(){var f=ToyTrainFixture.Instance;if(!f||!f.Ready)return;M.SetValue(f.Mover,Move);if(Jump){J.SetValue(f.Mover,.15f);Jump=false;}}void LateUpdate(){var f=ToyTrainFixture.Instance;if(f&&f.Ready)M.SetValue(f.Mover,Move);}}
    [DefaultExecutionOrder(20000)]public sealed class ToyTrainQA:MonoBehaviour
    {
        ToyTrainFixture f;TrainInputDriver input;Result result=new Result();Trial trial;bool filming;int frame;
        [Serializable]public class CheckRecord{public string name;public bool pass;public string detail;}
        [Serializable]public class Sample{public float time;public string phase;public ToyTrainFixture.State state;public Sample(ToyTrainFixture f,string p){time=Time.fixedTime;phase=p;state=new ToyTrainFixture.State(f);}}
        [Serializable]public class Trial{public string name;public bool passed;public List<Sample> events=new List<Sample>();public List<Sample> steps=new List<Sample>();}
        [Serializable]public class Result{public string method="Automatic original movement input-field/API and real Physics2D. NOT OS keys/Human.",mode;public bool finished;public int errors;public List<CheckRecord> checks=new List<CheckRecord>();public List<Trial> trials=new List<Trial>();}
        void Check(string name,bool pass,string detail){result.checks.Add(new CheckRecord{name=name,pass=pass,detail=detail});Debug.Log("TRAIN_CHECK "+name+" "+pass+" "+detail);}
        void Event(string label){trial.events.Add(new Sample(f,label));Debug.Log("TRAIN_EVENT "+trial.name+" "+label);}
        void Begin(string label){trial=new Trial{name=label};result.trials.Add(trial);}
        IEnumerator Start()
        {
            f=GetComponent<ToyTrainFixture>();input=gameObject.AddComponent<TrainInputDriver>();result.mode=ToyTrainFixture.Arg("-trainMode","matrix");
            yield return new WaitForSeconds(.5f);
            Check("Production player, no presentation-proof component",f.Body.GetComponent<RopeBodyVisual>()&&f.Body.transform.parent==null,"RopeBodyVisual remains Production, physical root unparented");
            Check("Train Kinematic body",f.Train.BodyType==RigidbodyType2D.Kinematic,"SolidSwingSurface initializes before the train-specific Kinematic setup");
            if(result.mode=="matrix")
            {
                yield return IdleRide();yield return Walking();yield return AirAttachRejected();
                foreach(float a in new[]{40f,45f,50f})yield return Route(a,false);
            }
            else yield return Route(45,ToyTrainFixture.Arg("-trainFilm")=="1");
            result.errors=f.Errors;result.finished=true;f.Write("TrainResult.json",result);
            yield return new WaitForSeconds(.1f);Quit(f.Errors==0?0:2);
        }
        IEnumerator Reset(){input.Move=0;input.Jump=false;f.Retry();yield return new WaitForSeconds(.6f);}
        IEnumerator Board()
        {
            input.Move=1;float end=Time.time+2;
            while(Time.time<end){if(f.Mover.SupportedTrain&&f.Body.position.x-f.Train.Position.x>-.15f)break;yield return new WaitForFixedUpdate();}
            input.Move=0;yield return new WaitForSeconds(.3f);Event("boarded");
        }
        IEnumerator ReadyToAttach()
        {
            float end=Time.time+13;
            while(Time.time<end&&f.Train.Position.x-ToyTrainFixture.Offset<5.05f)yield return new WaitForFixedUpdate();
        }
        IEnumerator IdleRide()
        {
            yield return Reset();Begin("Neutral ride through stop and reversals");yield return Board();
            float rel=f.Body.position.x-f.Train.Position.x,maxDrift=0,maxRelativeSpeed=0;bool allSupported=true;float end=Time.time+25;
            while(Time.time<end){maxDrift=Mathf.Max(maxDrift,Mathf.Abs(f.Body.position.x-f.Train.Position.x-rel));maxRelativeSpeed=Mathf.Max(maxRelativeSpeed,Mathf.Abs(f.Body.linearVelocity.x-f.Train.Velocity.x));allSupported&=f.Mover.SupportedTrain!=null;trial.steps.Add(new Sample(f,"neutral"));yield return new WaitForFixedUpdate();}
            trial.passed=allSupported&&maxDrift<.16f&&maxRelativeSpeed<.35f&&f.Train.Turns>=2;
            Check("Neutral carry + stop/reverse",trial.passed,"drift="+maxDrift+" relativeSpeed="+maxRelativeSpeed+" turns="+f.Train.Turns);Event("idle_end");
            yield return VerifyRetry("R from train");
        }
        IEnumerator Walking()
        {
            yield return Reset();Begin("Walk both ways on train and back to dock");yield return Board();
            float rel=f.Body.position.x-f.Train.Position.x;input.Move=-1;yield return new WaitForSeconds(.16f);float left=f.Body.position.x-f.Train.Position.x;
            input.Move=1;yield return new WaitForSeconds(.42f);float right=f.Body.position.x-f.Train.Position.x;input.Move=0;yield return new WaitForSeconds(.2f);
            Check("Walk relative to deck",left<rel-.2f&&right>left+.3f&&f.Mover.SupportedTrain,"left="+left+" right="+right);
            input.Move=-1;float end=Time.time+2;while(Time.time<end&&f.Mover.SupportedTrain)yield return new WaitForFixedUpdate();
            input.Move=0;yield return new WaitForSeconds(.35f);trial.passed=f.Mover.IsGrounded&&!f.Mover.SupportedTrain&&f.Body.position.x<f.Train.Position.x-2.4f;
            Check("Disembark to dock without carry",trial.passed,"worldV="+f.Body.linearVelocity+" grounded="+f.Mover.IsGrounded);Event("back_on_dock");
        }
        IEnumerator AirAttachRejected()
        {
            yield return Reset();Begin("Initial connection requires grounded");yield return Board();yield return ReadyToAttach();input.Jump=true;yield return new WaitForSeconds(.08f);
            float distance=Vector2.Distance(f.Body.position,f.Hook.transform.position);bool ground=f.Mover.IsGrounded;bool attach=f.Rope.TryAttach(f.Hook.transform.position);
            trial.passed=!ground&&distance<7&&!attach;Check("In-range initial airborne E rejected",trial.passed,"distance="+distance+" grounded="+ground+" attached="+attach);Event("air_attempt");yield return VerifyRetry("R from airborne");
        }
        IEnumerator Route(float angle,bool film)
        {
            yield return Reset();Begin("Board_Attach_Swing_Detach_Land_"+angle);
            if(film){frame=0;filming=true;Directory.CreateDirectory(Path.Combine(f.Output,"Frames"));StartCoroutine(Frames());}
            yield return Board();Check(trial.name+" natural board",f.Mover.SupportedTrain,"No diagnostic positioning on route");yield return ReadyToAttach();
            Event("before_E_on_car");bool attached=f.Rope.TryAttach(f.Hook.transform.position);Event("E_attached");
            Check(trial.name+" grounded initial E",attached&&f.Mover.IsGrounded&&f.Mover.SupportedTrain,"selected="+f.Rope.SelectedRopeLength+" distance="+Vector2.Distance(f.Body.position,f.Hook.transform.position));
            float rel=f.Body.position.x-f.Train.Position.x;yield return new WaitForSeconds(.35f);
            Check(trial.name+" attached no double carry",f.Mover.SupportedTrain&&Mathf.Abs(f.Body.position.x-f.Train.Position.x-rel)<.18f,"relative drift="+(f.Body.position.x-f.Train.Position.x-rel));
            input.Move=1;bool left=false,released=false;float end=Time.time+9;
            while(Time.time<end&&!f.Respawn.IsFailureVisible)
            {
                if(!left&&!f.Mover.SupportedTrain){left=true;Event("left_car_attached");}
                var d=f.Body.position-f.Rope.AnchorPoint;float a=Mathf.Atan2(d.x,-d.y)*Mathf.Rad2Deg;
                if(left&&!released&&a>=angle&&f.Body.linearVelocity.x>0&&f.Body.linearVelocity.y>0){Event("before_E_release");f.Rope.DetachAndRefund(true);released=true;Event("E_released");}
                trial.steps.Add(new Sample(f,released?"air_after_release":left?"swing":"car_walk"));
                if(released&&OnLanding())break;
                yield return new WaitForFixedUpdate();
            }
            input.Move=0;yield return new WaitForSeconds(.4f);Event("route_end");
            trial.passed=attached&&left&&released&&OnLanding()&&!f.Mover.SupportedTrain&&f.Resource.CurrentLength==24&&!f.Rope.IsAttached;
            Check(trial.name+" complete",trial.passed,"position="+f.Body.position+" resource="+f.Resource.CurrentLength+" noTrainSupport="+!f.Mover.SupportedTrain);
            filming=false;yield return VerifyRetry("R after landing route"+angle);
        }
        bool OnLanding()=>f.Mover.IsGrounded&&f.Body.position.x>f.Landing.bounds.min.x+.4f&&f.Body.position.x<f.Landing.bounds.max.x-.4f&&Mathf.Abs(f.Body.position.y-f.Landing.bounds.max.y-.6f)<.2f;
        IEnumerator VerifyRetry(string label)
        {
            input.Move=0;f.Retry();var immediately=new ToyTrainFixture.State(f);yield return new WaitForSeconds(.5f);
            Check(label,Vector2.Distance(f.Body.position,f.Spawn)<.18f&&f.Mover.IsGrounded&&!f.Mover.SupportedTrain&&!f.Rope.IsAttached&&f.Resource.CurrentLength==24&&f.Rope.SelectedRopeLength==7&&f.Builder.GeneratedPlatformCount==0&&Vector2.Distance(f.Train.Position,ToyTrainFixture.G(0,-.3f))<.01f&&f.Train.Velocity==Vector2.zero&&f.Train.WaitRemaining>3,"initial="+JsonUtility.ToJson(immediately));
        }
        IEnumerator Frames(){while(filming){yield return new WaitForEndOfFrame();if(!filming)break;var im=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Path.Combine(f.Output,"Frames/Frame_"+frame.ToString("D4")+".jpg"),im.EncodeToJPG(78));Destroy(im);frame++;}}
        static void Quit(int code){
            #if UNITY_EDITOR
            UnityEditor.EditorApplication.Exit(code);
            #else
            Application.Quit(code);
            #endif
        }
    }
